solution.FileTools.java:
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;

class FileTools {
    static Summary summarize(Path file) throws IOException {
        String text = Files.readString(file);
        List<String> lines = Files.readAllLines(file);
        int words = 0;
        String longest = "";
        for (String line : lines) {
            for (String w : line.trim().split("\\s+")) if (!w.isEmpty()) words++;
            if (line.length() > longest.length()) longest = line;
        }
        return new Summary(lines.size(), words, text.length(), longest);
    }

    static int copyMatching(Path in, Path out, String needle) throws IOException {
        if (out.getParent() != null) Files.createDirectories(out.getParent());
        String n = needle.toLowerCase();
        int written = 0;
        try (BufferedReader reader = Files.newBufferedReader(in);
             BufferedWriter writer = Files.newBufferedWriter(out)) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.toLowerCase().contains(n)) {
                    writer.write(line);
                    writer.newLine();
                    written++;
                }
            }
        }
        return written;
    }

    static List<String> findByExtension(Path dir, String extension) throws IOException {
        String suffix = "." + extension.toLowerCase();
        List<String> found = new ArrayList<>();
        try (Stream<Path> all = Files.walk(dir)) {
            for (Path p : all.toList()) {
                if (Files.isRegularFile(p) && p.getFileName().toString().toLowerCase().endsWith(suffix)) {
                    found.add(dir.relativize(p).toString().replace('\\', '/'));
                }
            }
        }
        Collections.sort(found);
        return found;
    }
}

unitTests:
test("summarizing a file", () -> {
    Path dir = Files.createTempDirectory("xenon-files");
    Path f = dir.resolve("poem.txt");
    Files.writeString(f, "the quick brown fox\njumps\n\nover the lazy dog\n");
    Summary s = FileTools.summarize(f);
    checkEq(s, new Summary(4, 9, 45L, "the quick brown fox"));
    Path empty = dir.resolve("empty.txt");
    Files.writeString(empty, "");
    checkEq(FileTools.summarize(empty), new Summary(0, 0, 0L, ""));
});

test("copying matching lines", () -> {
    Path dir = Files.createTempDirectory("xenon-files");
    Path log = dir.resolve("app.log");
    Files.write(log, List.of("INFO start", "ERROR disk full", "info done", "Error again"));
    Path out = dir.resolve("out/errors/errors.log");
    checkEq(FileTools.copyMatching(log, out, "error"), 2);
    checkEq(Files.readAllLines(out), List.of("ERROR disk full", "Error again"));
    checkThrows(IOException.class, () -> FileTools.copyMatching(dir.resolve("missing.log"), dir.resolve("x.log"), "a"));
});

test("finding files", () -> {
    Path dir = Files.createTempDirectory("xenon-files");
    Path root = dir.resolve("tree");
    Files.createDirectories(root.resolve("a/b"));
    Files.writeString(root.resolve("top.TXT"), "x");
    Files.writeString(root.resolve("a/notes.txt"), "x");
    Files.writeString(root.resolve("a/b/deep.txt"), "x");
    Files.writeString(root.resolve("a/b/image.png"), "x");
    checkEq(FileTools.findByExtension(root, "txt"), List.of("a/b/deep.txt", "a/notes.txt", "top.TXT"));
    checkEq(FileTools.findByExtension(root, "md"), List.of());
});

